"use server";

import { apiv3Get } from "@/lib/apiv3";

type MuseumListParams = {
    page?: number;
    per_page?: number;
    search?: string;
    filter?: {
        location_id?: number | string;
        city_id?: number | string;
        type_id?: number | string;
        name?: string;
    };
    sort?: string;
};

export default async function getMuseumList(params: MuseumListParams = {}) {
    const empty = { data: [], meta: { total: 0, current_page: 1, last_page: 1, per_page: 20 } };
    if (!process.env.NEXT_PUBLIC_APIV3_URL) return empty;

    try {
        const query = new URLSearchParams();
        if (params.page) query.set("page", String(params.page));
        if (params.per_page) query.set("per_page", String(params.per_page));
        if (params.search) query.set("search", params.search);
        if (params.sort) query.set("sort", params.sort);
        if (params.filter?.location_id) query.set("location_id", String(params.filter.location_id));
        if (params.filter?.city_id) query.set("city_id", String(params.filter.city_id));
        if (params.filter?.type_id) query.set("type_id", String(params.filter.type_id));
        if (params.filter?.name) query.set("name", params.filter.name);

        const res = await apiv3Get(`/museums?${query.toString()}`, { cache: "no-store" });
        if (!res.ok) return empty;

        return res.json();
    } catch {
        return empty;
    }
}
