"use server";

import { apiv3Get } from "@/lib/apiv3";
import type { FilterOption, MuseumFilterOptions } from "./museumFilterOptions.types";

export async function getMuseumCountries(): Promise<FilterOption[]> {
    if (!process.env.NEXT_PUBLIC_APIV3_URL) return [];
    try {
        const res = await apiv3Get(`/museums/countries`, { cache: "no-store" });
        if (!res.ok) return [];
        const json = await res.json();
        return json.data ?? json ?? [];
    } catch {
        return [];
    }
}

export async function getMuseumCities(countryId?: number | string): Promise<FilterOption[]> {
    if (!process.env.NEXT_PUBLIC_APIV3_URL) return [];
    try {
        const path = countryId
            ? `/museums/cities?country_id=${countryId}`
            : `/museums/cities`;
        const res = await apiv3Get(path, { cache: "no-store" });
        if (!res.ok) return [];
        const json = await res.json();
        return json.data ?? json ?? [];
    } catch {
        return [];
    }
}

export default async function getMuseumFilterOptions(): Promise<MuseumFilterOptions> {
    const [countries, cities] = await Promise.all([
        getMuseumCountries(),
        getMuseumCities(),
    ]);
    return { countries, cities };
}
